import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Download & system requirements","description":"","frontmatter":{},"headers":[],"relativePath":"en/download.md","filePath":"en/download.md","lastUpdated":null}'),s={name:"en/download.md"};function i(n,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="download-system-requirements" tabindex="-1">Download &amp; system requirements <a class="header-anchor" href="#download-system-requirements" aria-label="Permalink to &quot;Download &amp; system requirements&quot;">​</a></h1><p>DeepSeek Harness Shell is a cross-platform desktop app (Windows / macOS / Linux). Installers are published on GitHub Releases.</p><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h2><p>This documentation matches version <strong>0.1.5-alpha-3</strong>.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td>OS</td><td>Windows 10/11 (x64 / arm64), macOS, mainstream Linux (x64 / arm64)</td></tr><tr><td>Runtime</td><td>No Node.js needed (the <code>@deepseek-ai/dsh</code> kernel is managed by the app)</td></tr><tr><td>Network</td><td>Online access on first run to install the dsh kernel; localhost afterwards</td></tr></tbody></table><blockquote><p>The kernel <code>@deepseek-ai/dsh</code> is auto-detected. When missing, the app guides a one-click install (official registry.npmjs.org or the npmmirror mirror).</p></blockquote><h2 id="where-to-download" tabindex="-1">Where to download <a class="header-anchor" href="#where-to-download" aria-label="Permalink to &quot;Where to download&quot;">​</a></h2><ul><li>Open the <a href="https://github.com/XEonSKY/DeepSeek-Harness-Shell/releases" target="_blank" rel="noreferrer">Releases</a> page and pick the newest release.</li><li>Artifacts are named like <code>DeepSeek-Harness-Shell-&lt;version&gt;-&lt;platform&gt;-&lt;arch&gt;.&lt;ext&gt;</code>: <ul><li>Windows installer: <code>...-win-x64-setup.exe</code> / <code>...-win-arm64-setup.exe</code></li><li>macOS: <code>...-mac-x64.dmg</code> / <code>...-mac-arm64.dmg</code> (a matching <code>.zip</code> is published for auto-update)</li><li>Linux: <code>...-linux-x64.AppImage</code> / <code>...-linux-arm64.AppImage</code></li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">Choosing an architecture</p><p>Pick the asset matching your <strong>running process architecture</strong> (the installed package&#39;s arch): arm64 on ARM machines, x64 on Intel/AMD.</p></div><h2 id="verify-security" tabindex="-1">Verify &amp; security <a class="header-anchor" href="#verify-security" aria-label="Permalink to &quot;Verify &amp; security&quot;">​</a></h2><ul><li>Only download from the official Releases; app self-updates also go through GitHub.</li><li>If GitHub is slow on your network, set a public mirror prefix (e.g. <code>https://ghproxy.com</code>) under Settings → Network → GitHub mirror to speed up update downloads; leave it empty for a direct connection.</li><li>If you see an “unknown publisher” warning, allow it per your OS guidance (open-source apps are often unsigned).</li></ul>',12)])])}const p=t(s,[["render",i]]);export{h as __pageData,p as default};
